 final int app;int x,y,w,h,page,contactPage,ticks,detailPage;boolean requested,picking,confirm,busy;long sentAt,saleRevision;JsonObject data=new JsonObject();String target="",targetName="",draft="",photo="",notice="",detail="",nonce="";EditBox input;Map<String,PhotoStore.Picture> pictures=new HashMap<>();List<Path> recordings=List.of();int recordIndex;boolean deleting;
