 void request(String action){JsonObject o=new JsonObject();o.addProperty("action",action);if(action.endsWith("_sell"))o.addProperty("housing_revision",saleRevision);if(action.equals("land_buy"))o.addProperty("plot",selectedLand);if(action.equals("city_buy"))o.addProperty("floor",selectedFloor);o.addProperty("app",String.valueOf(app));o.addProperty("target",target);o.addProperty("page",page);send(o);}
 void send(JsonObject o){if(!ClientPlayNetworking.canSend(PhoneServices.Request.TYPE)){notice="このサーバーではスマホ機能を利用できません";return;}if(!o.has("app"))o.addProperty("app",String.valueOf(app));if(!o.has("page"))o.addProperty("page",page);if(!o.has("target"))o.addProperty("target",target);if(!o.get("action").getAsString().equals("view")){busy=true;sentAt=System.currentTimeMillis();}ClientPlayNetworking.send(new PhoneServices.Request(o.toString()));}
