  if(app==1&&!PhoneAudio.state.equals("idle")){if(PhoneAudio.state.equals("incoming"))button(x+12,y+111,135,"応答（マイクON）",()->PhoneAudio.command("accept"));if(PhoneAudio.state.equals("active")){button(x+12,y+111,135,PhoneAudio.muted?"マイクをON":"ミュート",()->{PhoneAudio.muted=!PhoneAudio.muted;rebuildWidgets();});button(x+155,y+111,44,"音量−",()->{PhoneAudio.adjustVolume(-.25f);rebuildWidgets();});button(x+203,y+111,44,"音量＋",()->{PhoneAudio.adjustVolume(.25f);rebuildWidgets();});}button(x+w-135,y+111,120,"通話を終了",()->PhoneAudio.command("end"));return;}
  if(picking){var f=friends();for(int j=0;j<contactRows();j++){int i=contactPage*contactRows()+j;if(i>=f.size())break;var r=f.get(i).getAsJsonObject();button(x+w-99,y+63+j*34,85,app==1?"電話する":"選択",()->{target=r.get("id").getAsString();targetName=r.get("name").getAsString();picking=false;page=0;detail="";data.remove("rows");if(app==1){PhoneAudio.command("dial "+target);}else request("view");rebuildWidgets();});}button(x+12,y+h-79,38,"<",()->{contactPage=Math.max(0,contactPage-1);rebuildWidgets();});button(x+56,y+h-79,38,">",()->{contactPage=Math.min(Math.max(0,(friends().size()-1)/contactRows()),contactPage+1);rebuildWidgets();});button(x+100,y+h-79,100,"フレンドを追加",()->minecraft.gui.setScreen(new FriendsScreen()));return;}
