    var btn=new PhoneScreen.NeonButton(x+12+(i%2)*(w-24)/2,y+59+(i/2)*24,(w-30)/2,19,"土地"+(n+1)+" / "+(free?"空き":row.get("mine").getAsBoolean()?"所有中":row.get("owner").getAsString()),b->{if(!busy&&free){selectedLand=n;landPicking=false;confirm=true;notice="土地"+(n+1)+" / 20,000 Cr を購入します";rebuildWidgets();}});
