 void postBody(GuiGraphicsExtractor g,String text,int yy,int max){var lines=new ArrayList<String>();while(!text.isEmpty()){String part=font.plainSubstrByWidth(text,w-24);if(part.isEmpty())break;lines.add(part);text=text.substring(part.length());}int pages=Math.max(1,(lines.size()+max-1)/max);detailPage%=pages;for(int i=0;i<max&&detailPage*max+i<lines.size();i++)g.text(font,lines.get(detailPage*max+i),x+12,yy+i*11,0xffd2e9ef);}
